func StreamLogsHandler(c *gin.Context) {
    containerID := c.Param("id")
    reader, err := dockerCli.ContainerLogs(c.Request.Context(), containerID, container.LogsOptions{
        ShowStdout: true, ShowStderr: true, Follow: true, Tail: "100",
    })
    if err != nil { c.AbortWithStatus(500); return }
    defer reader.Close()
    c.Stream(func(w io.Writer) bool {
        buf := make([]byte, 1024)
        n, err := reader.Read(buf)
        if err != nil { return false }
        w.Write(buf[:n])
        return true
    })
}

